; sets.asm -- chapter 29: eight shifted sets of pairs
; generated by gen29.py
        INCLUDE "msx.inc"
        OUTPUT "sets.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
count   EQU VARS                ; the frames left
at      EQU VARS + 1            ; the window's column, or the pixels gone by
table   EQU VARS + 3            ; the name table not shown: $18 or $1C, the high byte
ROWS    EQU 21
WIDTH   EQU 64
; A pixel a frame. The level's 23 pairs of tiles side by side, shifted 0 to 7
; pixels: eight sets of 23 patterns, 184 in all. Every frame the names of the
; next set go to the table not shown, during the paper, and R#2 shows them.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800, and $1C00 with R#2 = 7
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0780        ; the status line's letters
        ld hl, glyphs
        ld c, VDP_DATA
        ld b, 80
        otir
        VRAM_WRITE $2780        ; white on black
        ld b, 80
.tc:    ld a, $F1
        out (VDP_DATA), a
        djnz .tc
        VRAM_WRITE $1AA0        ; the status line, in both tables
        ld hl, status
        ld b, 96
        otir
        VRAM_WRITE $1EA0
        ld hl, status
        ld b, 96
        otir
        VRAM_WRITE $0000        ; the eight sets: 184 patterns
        ld hl, sets
        ld de, 1472
        call many
        VRAM_WRITE $2000        ; their colours
        ld hl, sets_c
        ld de, 1472
        call many
        ld hl, 0
        ld (at), hl
        ld a, $18
        ld (table), a
        call names              ; pixel 0 in the table at $1800
        ld a, $1C
        ld (table), a
        call step               ; pixel 1 in the table at $1C00, not shown
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        ld a, 64
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call show               ; what must change after the paper
m1:     call step               ; the next frame's work, while the paper is drawn
s1:     ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; show: the table written during the paper shown, with R#2
show:   ld a, (table)
        cp $18
        ld a, 6
        jr z, .r2
        inc a
.r2:    out (VDP_CTRL), a
        ld a, $80 | 2
        out (VDP_CTRL), a
        ld a, (table)
        xor $18 ^ $1C
        ld (table), a
        ret

; step: a pixel on; into the table not shown, the names of the set of the
; new shift: pair + shift x 23, the shift the pixels AND 7
step:   ld hl, (at)
        inc hl
        ld (at), hl
names:  xor a
        out (VDP_CTRL), a
        ld a, (table)
        or $40
        out (VDP_CTRL), a       ; the table's first name, for writing
        ld hl, (at)
        ld a, l
        and 7
        ld b, a
        xor a
.set:   dec b
        jp m, .x
        add a, 23
        jr .set
.x:     ld d, a                 ; D: the shift x 23, the set's first pattern
        srl h
        rr l
        srl h
        rr l
        srl h
        rr l                    ; HL: the window's column, the pixels / 8
        ld bc, pmap
        add hl, bc              ; its first pair
        ld e, ROWS
.row:   ld b, 32
.name:  ld a, (hl)              ;  8  the pair
        add a, d                ;  5  in the set of the shift
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        djnz .name              ; 14: 46 T-states a name
        ld bc, WIDTH - 1 - 32
        add hl, bc              ; the next row of pairs
        dec e
        jr nz, .row
        ret

; many: DE bytes from HL to the VDP, after an address is set (the display off)
many:   ld c, VDP_DATA
.byte:  outi
        dec de
        ld a, d
        or e
        jr nz, .byte
        ret
